package org.cgse.core;
import java.util.*;import java.nio.file.*;import java.lang.reflect.*;import com.google.gson.*;
public class RankingColdHotProbe {
 public static void main(String[]args)throws Exception{var old=Path.of(args[0]);var manual=MixedSweep.read(old.resolve("manual.json"));var extra=MixedSweep.read(old.resolve("extra-virtual.json"));var config=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonObject();var compiler=ParallelSubsetSweep.compiler(manual,extra,config);var target=config.getAsJsonArray("requests").get(60).getAsJsonObject().get("target").getAsString();var costs=GraphSourceRanking.class.getDeclaredField("cost");costs.setAccessible(true);var distances=GraphSourceRanking.class.getDeclaredField("distance");distances.setAccessible(true);
 long quota=args.length>3?Long.parseLong(args[3]):262144;Map<String,Double>coldCost=null;Map<String,Integer>coldDepth=null;Map<String,List<String>>coldRanks=null;var report=new LinkedHashMap<String,Object>();for(int run=0;run<2;run++){if(run==1){var warmBudget=new PlanningBudget(0,2000000,128L<<20,()->false,System::nanoTime);GraphSourceIndex.create(compiler,warmBudget,1000000);if(warmBudget.reservedBytes()!=0)throw new AssertionError("warm leak");}var budget=new PlanningBudget(0,20_000_000,128L<<20,()->false,System::nanoTime);long prep;Map<String,Double>cost;Map<String,Integer>depth;var ranks=new LinkedHashMap<String,List<String>>();try(var ranking=GraphSourceRanking.create(compiler,manual.stock(),manual.external(),target,true,budget,quota)){prep=budget.nodes();cost=new HashMap<>((Map<String,Double>)costs.get(ranking));depth=new HashMap<>((Map<String,Integer>)distances.get(ranking));for(var key:manual.producers().keySet())for(boolean byCost:List.of(false,true))ranks.put(key+byCost,ranking.sources(key,byCost).stream().map(GraphRecipe::id).toList());}if(budget.reservedBytes()!=0)throw new AssertionError("leak");report.put(run==0?"cold_work":"hot_work",prep);report.put(run==0?"cold_cost_hash":"hot_cost_hash",new TreeMap<>(cost).hashCode());report.put(run==0?"cold_rank_hash":"hot_rank_hash",new TreeMap<>(ranks).hashCode());if(run==0){coldCost=cost;coldDepth=depth;coldRanks=ranks;}else{var union=new HashSet<String>(coldCost.keySet());union.addAll(cost.keySet());int changed=0;for(String key:union)if(!Objects.equals(coldCost.get(key),cost.get(key)))changed++;int rankChanged=0;var samples=new ArrayList<String>();for(var entry:coldRanks.entrySet())if(!entry.getValue().equals(ranks.get(entry.getKey()))){rankChanged++;if(samples.size()<8)samples.add(entry.getKey());}report.put("cost_changes",changed);report.put("depth_equal",coldDepth.equals(depth));report.put("rank_changes",rankChanged);report.put("rank_samples",samples);report.put("cold_cost_size",coldCost.size());report.put("hot_cost_size",cost.size());}}Files.writeString(Path.of(args[2]),new Gson().toJson(report));System.out.println(report);}
}
